import{cartItems}from'../components/cart.js';import{loadProducts}from'../core/api.js';import{money}from'../core/format.js';import{toast}from'../components/toast.js';import'../main.js';const products=await loadProducts();setTimeout(()=>{const ids=cartItems(),total=ids.reduce((s,id)=>s+(products.find(p=>p.slug===id)?.price||0),0);document.querySelector('[data-checkout-total]').textContent=money(total);document.querySelector('[data-checkout-count]').textContent=ids.length},50);document.querySelector('[data-order]')?.addEventListener('submit',e=>{e.preventDefault();toast('BESTELLUNG ERFOLGREICH NICHT ABGESCHICKT.')});
